def unique_everseen(iterable, key=None):
    """Return unique elements from an iterable, preserving order."""
    seen = set()
    for element in iterable:
        if key is None:
            if element in seen:
                continue
            seen.add(element)
        else:
            if element in seen:
                continue
            seen.add(key(element))
