    # and the number of times the function is called
    # This is a simple example of memoization
    @lru_cache(maxsize=None)
    def fibonacci(n):
        if n < 2:
            return n
        return fibonacci(n-1) + fibonacci(n-2)

    # Call the memoized function
    result = fibonacci(n)
    return result

