class TestOverload(unittest.TestCase):
    def test_overload(self):
        class A:
            def __init__(self, x):
                self.x = x

            def __init__(self, x, y):
                self.x = x
                self.y = y

        a = A(1)
        self.assertEqual(a.x, 1)
        self.assertEqual(a.y, None)

        a = A(1, 2)
        self.assertEqual(a.x, 1)

